functionList.push(['media.view','View media storage','Browse media within your account scope.','Media'],['media.manage','Manage media','Upload, rename, replace and organise media.','Media'],['media.approve','Approve media','Approve or reject media after accessibility review.','Media'],['media.delete','Move media to trash','Trash and restore media without permanent deletion.','Media']);
menuIconPaths.media='M3 3h18v18H3z M3 17l5-5 5 5 3-3 5 5 M16 7h.01';navSections[1][1].splice(2,0,['media','Media storage','',null]);
const pageBeforeMedia=pageAllowed;pageAllowed=function(page){if(page==='media')return ['media.view','media.manage','media.approve','media.delete'].some(can);return pageBeforeMedia(page)};
const MEDIA_KEY='ngyn-media-metadata-v1';let mediaData;try{mediaData=JSON.parse(localStorage.getItem(MEDIA_KEY))||null}catch{}
mediaData=mediaData||{folders:[{id:'brand',name:'Brand assets',owner:'admin'},{id:'services',name:'Service updates',owner:'admin'},{id:'community',name:'Community & recreation',owner:'admin'}],assets:Array.from({length:20},(_,i)=>({id:'media-seed-'+i,name:['autumn-collection','transit-service','community-trail','city-waterfront','swim-program'][i%5]+'-'+(i+1)+'.jpg',type:'image/jpeg',folder:['services','services','community','brand','community'][i%5],url:samplePhoto(i,1200,i%3===0?1200:630),photoIndex:i%samplePhotos.length,source:samplePhotos[i%samplePhotos.length].source,credit:samplePhotos[i%samplePhotos.length].author+' / Unsplash',width:1200,height:i%3===0?1200:630,bytes:null,alt:i%6===0?'':samplePhotos[i%samplePhotos.length].alt,tags:['Municipal',i%2?'Service':'Community'],status:i%6===0?'Needs review':'Approved',channelIds:[assetsData.channels[i%assetsData.channels.length].id],owner:'admin',updated:new Date(Date.now()-i*86400000).toISOString(),versions:[],trashed:false}))};
let mediaFolder='All',mediaQuery='',mediaSort='Newest',mediaType='All',mediaLayout='grid',mediaSelected=new Set(),mediaPickerCallback=null;
const mediaObjectUrls=new Map();
function mayBrowseMedia(a){return isAdmin()||a.owner===viewUser||a.channelIds.some(accountAllowed)}
function mayManageMedia(a,permission='media.manage'){return can(permission)&&mayBrowseMedia(a)}
function mediaStorageSummary(){const local=mediaData.assets.filter(a=>a.blobId).reduce((sum,a)=>sum+(a.bytes||0),0);return local<1048576?(local/1024).toFixed(1)+' KB local':(local/1048576).toFixed(1)+' MB local'}
function saveMedia(){try{localStorage.setItem(MEDIA_KEY,JSON.stringify(mediaData));return true}catch{toast('Media metadata could not be saved. Browser storage may be full.');return false}}
function openMediaDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('ngyn-media-files-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function putMediaBlob(id,blob){const db=await openMediaDB();await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function getMediaBlob(id){const db=await openMediaDB();const blob=await new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly');const r=tx.objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.close();return blob}
async function mediaURL(a){if(a.blobId){if(!mediaObjectUrls.has(a.blobId)){const blob=await getMediaBlob(a.blobId);if(blob)mediaObjectUrls.set(a.blobId,URL.createObjectURL(blob))}return mediaObjectUrls.get(a.blobId)||''}return a.url||''}
function mediaPreview(a){if(a.type.startsWith('image/'))return `<img data-media-preview="${a.id}" ${a.url?'src="'+a.url+'"':''} alt="${safe(a.alt||a.name)}" loading="lazy" referrerpolicy="no-referrer">`;return `<div class="media-file-placeholder">${a.type.startsWith('video/')?'▶':'PDF'}<small>${safe(a.name)}</small></div>`}
function sizeText(a){return a.bytes===null?'Remote sample':a.bytes<1048576?(a.bytes/1024).toFixed(1)+' KB':(a.bytes/1048576).toFixed(1)+' MB'}
function visibleMediaAssets(){let records=mediaData.assets.filter(mayBrowseMedia).filter(a=>mediaFolder==='Trash'?a.trashed:!a.trashed&&(mediaFolder==='All'||a.folder===mediaFolder)).filter(a=>(a.name+' '+a.alt+' '+a.tags.join(' ')).toLowerCase().includes(mediaQuery.toLowerCase())).filter(a=>mediaType==='All'||mediaType==='Images'&&a.type.startsWith('image/')||mediaType==='Videos'&&a.type.startsWith('video/')||mediaType==='Documents'&&a.type==='application/pdf');records.sort(mediaSort==='Name'?(a,b)=>a.name.localeCompare(b.name):mediaSort==='Oldest'?(a,b)=>a.updated.localeCompare(b.updated):(a,b)=>b.updated.localeCompare(a.updated));return records}
function showMediaStorage(){document.querySelector('.crumb strong').textContent='Media storage';const folderName=mediaFolder==='All'?'All files':mediaFolder==='Trash'?'Trash':mediaData.folders.find(f=>f.id===mediaFolder)?.name||'All files';document.querySelector('#main').innerHTML=heading('Media storage','Your team’s reusable photos, videos and documents.',`<button class="btn" id="media-mock-integrations">Mock integrations</button><span class="badge">${mediaStorageSummary()}</span>${can('media.manage')?'<button class="btn" id="media-new-folder">＋ Folder</button><button class="btn primary" id="media-upload">↑ Upload</button>':''}`)+`<div class="ops-filters"><label>Library<select id="media-library"><option value="All" ${mediaFolder==='All'?'selected':''}>My media</option><option value="Trash" ${mediaFolder==='Trash'?'selected':''}>Trash</option>${mediaData.folders.map(f=>`<option value="${f.id}" ${mediaFolder===f.id?'selected':''}>${safe(f.name)}</option>`).join('')}</select></label><label class="grow">Search<input id="media-search" value="${safe(mediaQuery)}" placeholder="Search name, ALT text or tags…"></label><label>Sort<select id="media-sort">${['Newest','Oldest','Name'].map(s=>`<option ${s===mediaSort?'selected':''}>${s}</option>`)}</select></label><label>Type<select id="media-type">${['All','Images','Videos','Documents'].map(s=>`<option ${s===mediaType?'selected':''}>${s}</option>`)}</select></label><div class="switch media-layout-switch"><button id="media-grid" class="${mediaLayout==='grid'?'active':''}" aria-label="Grid view" aria-pressed="${mediaLayout==='grid'}">${menuIcon('content')}</button><button id="media-list" class="${mediaLayout==='list'?'active':''}" aria-label="List view" aria-pressed="${mediaLayout==='list'}">${menuIcon('audit')}</button></div></div><section class="media-folder-section"><h3>Folders</h3><div class="media-folders">${mediaData.folders.map(f=>`<div class="media-folder"><button data-open-media-folder="${f.id}">${menuIcon('assets')}<span>${safe(f.name)}</span><small>${mediaData.assets.filter(a=>mayBrowseMedia(a)&&!a.trashed&&a.folder===f.id).length}</small></button>${can('media.manage')&&(isAdmin()||f.owner===viewUser)?`<button class="media-folder-more" data-edit-media-folder="${f.id}" aria-label="Manage ${safe(f.name)} folder">•••</button>`:''}</div>`).join('')}</div></section><div class="media-files-heading"><div><h3>${safe(folderName)}</h3><span class="ops-muted" id="media-file-count"></span></div><div id="media-bulk-actions"></div></div><section id="media-files"></section><input id="media-upload-input" type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,application/pdf" class="hidden"><p class="ops-muted">Browser-local demo storage (IndexedDB). Remote samples show credits; file sizes are shown only when known. Trash is recoverable. No real Canva or Drive connection.</p>`;document.querySelector('#media-library').onchange=e=>{mediaFolder=e.target.value;mediaSelected.clear();showMediaStorage()};document.querySelector('#media-search').oninput=e=>{mediaQuery=e.target.value;renderMediaFiles()};document.querySelector('#media-sort').onchange=e=>{mediaSort=e.target.value;renderMediaFiles()};document.querySelector('#media-type').onchange=e=>{mediaType=e.target.value;renderMediaFiles()};document.querySelector('#media-grid').onclick=()=>{mediaLayout='grid';showMediaStorage()};document.querySelector('#media-list').onclick=()=>{mediaLayout='list';showMediaStorage()};document.querySelector('#media-upload')?.addEventListener('click',()=>document.querySelector('#media-upload-input').click());document.querySelector('#media-upload-input').onchange=e=>uploadMediaFiles([...e.target.files]);document.querySelector('#media-new-folder')?.addEventListener('click',()=>editMediaFolder());document.querySelectorAll('[data-open-media-folder]').forEach(b=>b.onclick=()=>{mediaFolder=b.dataset.openMediaFolder;mediaSelected.clear();showMediaStorage()});document.querySelectorAll('[data-edit-media-folder]').forEach(b=>b.onclick=()=>editMediaFolder(b.dataset.editMediaFolder));document.querySelector('#media-mock-integrations').onclick=()=>assetModal('Media integrations · mocked',`<p class="form-description">Canva editing and Drive storage are planned integration points. These controls do not authenticate or contact another service.</p><div class="actions"><button class="btn" id="media-canva-demo">Mock Connect Canva</button><button class="btn" id="media-drive-demo">Mock Connect Drive</button></div><p id="media-mock-result" class="ops-muted">No connection configured.</p>`);document.addEventListener('click',mediaIntegrationClick,{once:true});renderMediaFiles()}
function mediaIntegrationClick(e){if(e.target.id==='media-canva-demo'||e.target.id==='media-drive-demo')document.querySelector('#media-mock-result').textContent='Simulated connection request only. No account was connected.';else if(document.querySelector('#media-mock-result'))document.addEventListener('click',mediaIntegrationClick,{once:true})}
function renderMediaFiles(){const records=visibleMediaAssets();document.querySelector('#media-file-count').textContent=records.length+' files';const bulk=document.querySelector('#media-bulk-actions');bulk.innerHTML=mediaSelected.size?`<span class="badge">${mediaSelected.size} selected</span> ${can('media.manage')?'<button class="btn" id="media-bulk-move">Move to folder</button>':''} ${can('media.delete')?`<button class="btn" id="media-bulk-trash">${mediaFolder==='Trash'?'Restore':'Move to trash'}</button>`:''}`:'';document.querySelector('#media-files').innerHTML=!records.length?'<div class="ops-empty"><h3>No files found</h3><p>Try another folder or search, or upload media you can access.</p></div>':mediaLayout==='grid'?`<div class="media-storage-grid">${records.map(a=>`<article class="media-storage-card"><button class="media-thumbnail" data-open-media="${a.id}">${mediaPreview(a)}<span class="media-thumbnail-caption">${safe(a.name)}</span></button><label class="media-select"><input type="checkbox" data-select-media="${a.id}" ${mediaSelected.has(a.id)?'checked':''} aria-label="Select ${safe(a.name)}"></label><button class="media-card-menu" data-menu-media="${a.id}" aria-label="Actions for ${safe(a.name)}">•••</button><div class="media-card-info"><span>${sizeText(a)} · ${a.width&&a.height?a.width+' × '+a.height:'Dimensions unavailable'}</span><span class="badge ${a.status==='Approved'?'ok':'warn'}">${a.status}</span></div></article>`).join('')}</div>`:`<div class="user-panel table-wrap"><table class="table user-table"><thead><tr><th>Select</th><th>Media</th><th>Name</th><th>Updated</th><th>File size</th><th>Dimensions</th><th>Actions</th></tr></thead><tbody>${records.map(a=>`<tr><td><input type="checkbox" data-select-media="${a.id}" ${mediaSelected.has(a.id)?'checked':''} aria-label="Select ${safe(a.name)}"></td><td><button class="media-list-thumb" data-open-media="${a.id}" aria-label="Open ${safe(a.name)}">${mediaPreview(a)}</button></td><td><button class="asset-link" data-open-media="${a.id}">${safe(a.name)}</button><br><small>${a.status}</small></td><td>${timeLabel(a.updated)}</td><td>${sizeText(a)}</td><td>${a.width&&a.height?a.width+' × '+a.height+' px':'Unavailable'}</td><td><button class="btn" data-menu-media="${a.id}" aria-label="Actions for ${safe(a.name)}">•••</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-select-media]').forEach(c=>c.onchange=()=>{c.checked?mediaSelected.add(c.dataset.selectMedia):mediaSelected.delete(c.dataset.selectMedia);renderMediaFiles()});document.querySelectorAll('[data-open-media]').forEach(b=>b.onclick=()=>openMediaDetails(b.dataset.openMedia));document.querySelectorAll('[data-menu-media]').forEach(b=>b.onclick=()=>mediaActions(b.dataset.menuMedia));document.querySelector('#media-bulk-move')?.addEventListener('click',()=>moveMedia([...mediaSelected]));document.querySelector('#media-bulk-trash')?.addEventListener('click',()=>trashMedia([...mediaSelected],mediaFolder!=='Trash'));hydrateMediaPreviews()}
async function hydrateMediaPreviews(){for(const image of document.querySelectorAll('img[data-media-preview]')){const a=mediaData.assets.find(a=>a.id===image.dataset.mediaPreview);if(a?.blobId){try{image.src=await mediaURL(a)}catch{image.alt='Local file unavailable in this browser'}}}}
function editMediaFolder(id){const f=mediaData.folders.find(f=>f.id===id);if(!can('media.manage')||f&&!(isAdmin()||f.owner===viewUser))return;assetModal(f?'Manage folder':'Create folder',`<form id="media-folder-form"><div class="field"><label for="media-folder-name">Folder name</label><input id="media-folder-name" required maxlength="100" value="${safe(f?.name||'')}"></div><div class="actions"><button class="btn primary" type="submit">${f?'Save name':'Create folder'}</button>${f?'<button class="btn" id="remove-media-folder" type="button">Remove folder only</button>':''}</div><p class="ops-muted">Removing a folder returns its files to My Media. Files are not deleted.</p></form>`);document.querySelector('#media-folder-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#media-folder-name').value.trim();if(!name)return;if(mediaData.folders.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase())){toast('That folder name already exists.');return}f?f.name=name:mediaData.folders.push({id:crypto.randomUUID(),name,owner:viewUser});saveMedia();close();showMediaStorage()};document.querySelector('#remove-media-folder')?.addEventListener('click',()=>{mediaData.assets.forEach(a=>{if(a.folder===id)a.folder=null});mediaData.folders=mediaData.folders.filter(x=>x.id!==id);if(mediaFolder===id)mediaFolder='All';saveMedia();close();showMediaStorage();toast('Folder removed; files kept in My Media.')})}
async function inspectMediaFile(file){const blobURL=URL.createObjectURL(file);try{if(file.type.startsWith('image/'))return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve({width:image.naturalWidth,height:image.naturalHeight});image.onerror=()=>reject(new Error('Invalid image'));image.src=blobURL});return {width:null,height:null}}finally{URL.revokeObjectURL(blobURL)}}
async function uploadMediaFiles(files,replaceId){if(!can('media.manage'))return;const allowed=['image/png','image/jpeg','image/webp','image/gif','video/mp4','video/webm','application/pdf'];let count=0;for(const file of files){if(!allowed.includes(file.type)||file.size>20*1024*1024){toast('Skipped '+file.name+': supported files up to 20 MB.');continue}try{const dimensions=await inspectMediaFile(file),blobId=crypto.randomUUID();await putMediaBlob(blobId,file);const a=replaceId?mediaData.assets.find(a=>a.id===replaceId):null;if(a&&!mayManageMedia(a))return;if(a){a.versions.push({blobId:a.blobId||null,url:a.url||null,updated:a.updated,bytes:a.bytes});Object.assign(a,{blobId,url:null,type:file.type,bytes:file.size,...dimensions,status:'Needs review',updated:nowISO()})}else mediaData.assets.unshift({id:crypto.randomUUID(),name:file.name,type:file.type,folder:['All','Trash'].includes(mediaFolder)?null:mediaFolder,blobId,bytes:file.size,...dimensions,alt:'',tags:[],status:'Needs review',channelIds:[],owner:viewUser,updated:nowISO(),versions:[],trashed:false});count++}catch(error){toast('Could not store '+file.name+'. Check browser storage availability.')}}if(count){saveMedia();logOps(replaceId?'Media replaced':'Media uploaded',count+' browser-local file(s); review required.');close();showMediaStorage();toast(count+' file(s) stored in this browser.')}}
function mediaActions(id){const a=mediaData.assets.find(a=>a.id===id);if(!a||!mayBrowseMedia(a))return;assetModal('File actions',`<h3>${safe(a.name)}</h3><div class="media-action-list"><button class="btn" data-file-action="details">Preview / edit details</button><button class="btn" data-file-action="link">Get local demo link</button>${mayManageMedia(a)?'<button class="btn" data-file-action="replace">Replace file</button><button class="btn" data-file-action="move">Move to folder</button><button class="btn" data-file-action="rename">Rename</button>':''}<button class="btn" data-file-action="download">${a.blobId?'Download stored file':'Open original photo source'}</button>${mayManageMedia(a,'media.delete')?`<button class="btn" data-file-action="trash">${a.trashed?'Restore from trash':'Move to trash'}</button>`:''}</div><p id="media-link-output" class="ops-muted"></p><input id="media-replace-file" class="hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,application/pdf">`);document.querySelectorAll('[data-file-action]').forEach(b=>b.onclick=async()=>{const cmd=b.dataset.fileAction;if(cmd==='details')openMediaDetails(id);if(cmd==='link'){const link=location.origin+location.pathname+'#media='+encodeURIComponent(id);document.querySelector('#media-link-output').textContent=link+' — local demo link, not a public file URL.';try{await navigator.clipboard.writeText(link);toast('Local demo link copied.')}catch{toast('Select and copy the displayed link.')}}if(cmd==='move')moveMedia([id]);if(cmd==='rename')renameMedia(id);if(cmd==='replace'){document.querySelector('#media-replace-file').onchange=e=>uploadMediaFiles([...e.target.files],id);document.querySelector('#media-replace-file').click()}if(cmd==='download'){if(a.blobId){const url=await mediaURL(a),link=document.createElement('a');link.href=url;link.download=a.name;link.click()}else{const link=document.createElement('a');link.href=a.source;link.target='_blank';link.rel='noopener noreferrer';link.click()}}if(cmd==='trash')trashMedia([id],!a.trashed)})}
function renameMedia(id){const a=mediaData.assets.find(a=>a.id===id);if(!a||!mayManageMedia(a))return;assetModal('Rename file',`<form id="media-rename-form"><div class="field"><label for="media-rename-name">File name</label><input id="media-rename-name" required maxlength="180" value="${safe(a.name)}"></div><button class="btn primary" type="submit">Save name</button></form>`);document.querySelector('#media-rename-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#media-rename-name').value.trim();if(!name)return;a.name=name;a.updated=nowISO();saveMedia();close();showMediaStorage()}}
function moveMedia(ids){const assets=mediaData.assets.filter(a=>ids.includes(a.id)&&mayManageMedia(a));if(!assets.length)return;assetModal('Move files to folder',`<form id="media-move-form"><p class="form-description">${assets.length} selected file(s)</p><div class="field"><label for="media-target-folder">Destination folder</label><select id="media-target-folder"><option value="">My media (no folder)</option>${mediaData.folders.map(f=>`<option value="${f.id}">${safe(f.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Move files</button></form>`);document.querySelector('#media-move-form').onsubmit=e=>{e.preventDefault();assets.forEach(a=>{a.folder=document.querySelector('#media-target-folder').value||null;a.updated=nowISO()});saveMedia();mediaSelected.clear();close();showMediaStorage()}}
function trashMedia(ids,trashed){const assets=mediaData.assets.filter(a=>ids.includes(a.id)&&mayManageMedia(a,'media.delete'));if(!assets.length)return;assets.forEach(a=>{a.trashed=trashed;a.updated=nowISO()});saveMedia();logOps(trashed?'Media moved to recoverable trash':'Media restored',assets.length+' file(s).');mediaSelected.clear();close();showMediaStorage();toast(trashed?'Files moved to trash. Restore them anytime.':'Files restored.')}
async function openMediaDetails(id){const a=mediaData.assets.find(a=>a.id===id);if(!a||!mayBrowseMedia(a))return;const url=await mediaURL(a);assetModal('Media details',`<div class="media-details-layout"><div>${a.type.startsWith('image/')?`<img class="media-detail-image" src="${url}" alt="${safe(a.alt||a.name)}" referrerpolicy="no-referrer">`:a.type.startsWith('video/')?`<video class="media-detail-image" controls src="${url}"></video>`:'<div class="media-file-placeholder">PDF document</div>'}${a.source?`<p class="ops-muted"><a href="${a.source}" target="_blank" rel="noopener noreferrer">${safe(a.credit)} · source</a></p>`:''}<p class="ops-muted">${sizeText(a)} · ${a.width&&a.height?a.width+' × '+a.height:'Dimensions unavailable'}<br>${a.versions.length+1} version(s)</p></div><form id="media-details-form"><h3>${safe(a.name)}</h3><span class="badge ${a.status==='Approved'?'ok':'warn'}">${a.status}</span><div class="field"><label for="media-detail-alt">ALT text / accessible description</label><textarea id="media-detail-alt" rows="4" ${mayManageMedia(a)?'':'disabled'}>${safe(a.alt)}</textarea></div><div class="field"><label for="media-detail-tags">Tags · comma-separated</label><input id="media-detail-tags" value="${safe(a.tags.join(', '))}" ${mayManageMedia(a)?'':'disabled'}></div><div class="actions">${mayManageMedia(a)?'<button type="submit" class="btn primary">Save details</button>':''}${can('media.approve')?'<button type="button" class="btn" id="approve-media">Approve</button><button type="button" class="btn" id="reject-media">Reject</button>':''}${can('content.create')&&a.type.startsWith('image/')&&a.status==='Approved'&&!a.trashed?'<button type="button" class="btn" id="use-media-post">Use in post</button>':''}</div><p class="ops-muted">Changes to accessibility details return the asset to review. Image approval requires ALT text. Video caption workflows are not implemented.</p></form></div>`);document.querySelector('.modal-box').classList.add('wide-dialog');document.querySelector('#media-details-form').onsubmit=e=>{e.preventDefault();if(!mayManageMedia(a))return;a.alt=document.querySelector('#media-detail-alt').value.trim();a.tags=document.querySelector('#media-detail-tags').value.split(',').map(t=>t.trim()).filter(Boolean);a.status='Needs review';a.updated=nowISO();saveMedia();close();showMediaStorage();toast('Details saved; approval required.')};document.querySelector('#approve-media')?.addEventListener('click',()=>{if(!can('media.approve'))return;if(a.type.startsWith('image/')&&!a.alt.trim()){toast('Save an ALT description before approving this image.');return}a.status='Approved';a.updated=nowISO();saveMedia();close();showMediaStorage()});document.querySelector('#reject-media')?.addEventListener('click',()=>{if(!can('media.approve'))return;a.status='Rejected';a.updated=nowISO();saveMedia();close();showMediaStorage()});document.querySelector('#use-media-post')?.addEventListener('click',()=>selectMediaForComposer(a))}
async function selectMediaForComposer(a){if(!can('content.create')||!mayBrowseMedia(a)||a.trashed||a.status!=='Approved'||!a.type.startsWith('image/')){toast('Choose an approved accessible image.');return}const url=await mediaURL(a);if(!singleDraft)initializeSingleDraft();if(a.blobId){const blob=await getMediaBlob(a.blobId);if(blob.size>600*1024){toast('Composer demo accepts local images up to 600 KB. Use a smaller version.');return}singleDraft.mediaUrl=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(blob)})}else{singleDraft.mediaUrl=url;singleDraft.photo=a.photoIndex||0}singleDraft.alt=a.alt;singleDraft.mediaAssetId=a.id;singleDraft.mediaCredit=a.credit||'Local demo image';saveSingleDraft();close();renderWorkspace('composer');toast('Media selected for the post. Nothing published.')}
const renderBeforeMedia=renderWorkspace;renderWorkspace=function(page=currentPage){renderBeforeMedia(page);if(page==='media'&&pageAllowed('media'))showMediaStorage()};
const composerBeforeMedia=renderSingleComposer;renderSingleComposer=function(){composerBeforeMedia();if(['media.view','media.manage','media.approve','media.delete'].some(can)){const button=document.createElement('button');button.className='btn';button.id='composer-browse-media';button.textContent='▧ Browse media storage';button.onclick=chooseStoredMedia;document.querySelector('.composer-photo-choices').insertAdjacentElement('afterend',button)}};
function chooseStoredMedia(){const assets=mediaData.assets.filter(a=>mayBrowseMedia(a)&&!a.trashed&&a.status==='Approved'&&a.type.startsWith('image/'));assetModal('Choose stored media',`<p class="form-description">Approved images within your account scope.</p><div class="media-storage-grid picker-media-grid">${assets.map(a=>`<button class="media-pick-item" data-pick-stored="${a.id}">${mediaPreview(a)}<strong>${safe(a.name)}</strong></button>`).join('')||'<p>No approved images available.</p>'}</div>`);document.querySelectorAll('[data-pick-stored]').forEach(b=>b.onclick=()=>selectMediaForComposer(mediaData.assets.find(a=>a.id===b.dataset.pickStored)));hydrateMediaPreviews()}
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#media=')){const id=decodeURIComponent(location.hash.slice(7));if(pageAllowed('media')){renderWorkspace('media');openMediaDetails(id)}}});
